import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/saving.dart';
import '../../../data/repositories/group_repository.dart';
import '../../../l10n/app_localizations.dart';
import '../../widgets/app_drawer.dart';
class SavingsScreen extends StatelessWidget{const SavingsScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();final l=AppLocalizations.of(context);return Scaffold(appBar:AppBar(title:Text(l.t('savings'))),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[Text(l.t('savingsHistory'),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.savings(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return Text(l.t('loading'));if(s.hasError)return Text('${l.t('error')}: ${s.error}');final data=s.data??[];if(data.isEmpty)return Text(l.t('noData'));return Column(children:data.map((x)=>Card(child:ListTile(title:Text('TZS ${x.amount}'),subtitle:Text('${x.memberId} • ${x.date}')))).toList());})]));}void _add(BuildContext context,GroupRepository repo){final l=AppLocalizations.of(context);final key=GlobalKey<FormState>();final member=TextEditingController();final amount=TextEditingController();var loading=false;showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(context,setState)=>AlertDialog(title:Text(l.t('recordSavings')),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:member,decoration:InputDecoration(labelText:l.t('memberId')),validator:(v)=>(v==null||v.isEmpty)?l.t('required'):null),TextFormField(controller:amount,decoration:InputDecoration(labelText:l.t('amount')),keyboardType:TextInputType.number,validator:(v)=>(double.tryParse(v??'')??0)<=0?l.t('validAmount'):null)])),actions:[FilledButton(onPressed:loading?null:()async{if(!key.currentState!.validate())return;setState(()=>loading=true);await repo.addSaving(Saving(id:'',memberId:member.text,amount:double.parse(amount.text),date:DateTime.now()));if(context.mounted)Navigator.pop(context);},child:Text(loading?l.t('pleaseWait'):l.t('save')))])));}}
